+        send.addClickShortcut(Key.ENTER);
+
+        form.add(new HorizontalLayout(send));
+        return form;
+    }
+
+    private Grid<Message> createGrid() {
+        sent.addColumn(Message::name).setKey("name").setHeader("Name")
+                .setAutoWidth(true);
+        sent.addColumn(Message::text).setKey("message").setHeader("Message")
+                .setFlexGrow(1);
+        sent.addColumn(Message::email).setKey("email").setHeader("Email")
+                .setAutoWidth(true);
+        sent.addColumn(Message::phone).setKey("phone").setHeader("Phone")
+                .setAutoWidth(true);
+        return sent;
+    }
+
+    private List<TextFieldBase<?, ?>> fields() {
+        return List.of(name, email, phone, message);
+    }
+
+    private void configureField(TextFieldBase<?, ?> field) {
+        // Send the value on every keystroke, so that the Send button state and
+        // the unsent-input check always see what the user sees.
+        field.setValueChangeMode(ValueChangeMode.EAGER);
+        field.setClearButtonVisible(true);
+        // Validation happens when Send is pressed, and nowhere else.
+        field.setManualValidation(true);
+        field.addValueChangeListener(event -> onEdit());
