+        if (!send.isEnabled()) {
+            return;
+        }
+
+        String enteredName = value(name);
+        String enteredEmail = value(email);
+        String enteredPhone = value(phone);
+        String enteredMessage = value(message);
+
+        clearErrors();
+        boolean valid = true;
+
+        if (enteredName.isBlank()) {
+            valid = markInvalid(name, "Name is required");
+        }
+        if (!enteredEmail.isBlank()
+                && !EMAIL_PATTERN.matcher(enteredEmail.trim()).matches()) {
+            valid = markInvalid(email, "Enter a valid e-mail address");
+        } else if (enteredEmail.isBlank() && enteredPhone.isBlank()) {
+            valid = markInvalid(email,
+                    "Give an e-mail address or a phone number");
+        }
+        if (enteredMessage.isBlank()) {
+            valid = markInvalid(message, "Message is required");
+        } else if (enteredMessage.length() > MAX_MESSAGE_LENGTH) {
+            valid = markInvalid(message, "Message must be at most "
+                    + MAX_MESSAGE_LENGTH + " characters");
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        store.add(new Message(enteredName.trim(), enteredEmail.trim(),
+                enteredPhone.trim(), enteredMessage.trim()));
+        refreshGrid();
+        clearForm();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
