+    private boolean markInvalid(TextFieldBase<?, ?> field,
+            String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+        return false;
+    }
+
+    private void clearErrors() {
+        fields().forEach(field -> {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        });
+    }
+
+    private void clearForm() {
+        clearing = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearing = false;
+        }
+    }
+
+    private void refreshGrid() {
+        sent.setItems(store.getMessages());
+    }
+
+    private static String value(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value;
+    }
+
+    private boolean hasUnsentInput() {
+        return !value(name).isEmpty() || !value(email).isEmpty()
+                || !value(phone).isEmpty() || !value(message).isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsentInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard this message?");
